entries[220610] = { ["name"] = "Rune of Mental Dexterity", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your helm with the Mental Dexterity rune:\n\nDealing damage with Stormstrike increases your Attack Power by 150% of your Intellect, and your spell damage by 35% of your total Attack Power for 30 sec.\n\"Teaches you a new Engraving ability.\"" }
