entries[220965] = { ["name"] = "Scalebane Greataxe", ["text"] = "Binds when picked up\nTwo-Hand Axe\n138 - 207 Damage Speed 3.40\n(50.74 damage per second)\nDurability 120 / 120\nRequires Level 50\nEquip: +117 Attack Power when fighting Dragonkin.\n\"Hair of the dog, scale of the dragon.\"" }
entries[221008] = { ["name"] = "Supply Shipment", ["text"] = "Binds when picked up\n\"Deliver to a supply officer for a substantial reward.\"" }
