entries[221261] = { ["name"] = "Wildwhisper Draught", ["text"] = "Binds when picked up\nUnique\nUse: Summon the Spirit of Agamaggan. May only be used at the top of the Spiral of Thorns in Razorfen Downs, after defeating all nearby enemies. (5 Sec Cooldown)" }
