entries[221321] = { ["name"] = "Atal'ai Signet of Might", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Permanently adds 15 attack power to a shoulder slot item." }
entries[221322] = { ["name"] = "Atal'ai Signet of Mojo", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Permanently adds to a shoulder slot item increased damage and healing done by magical spells and effects by 9." }
entries[221323] = { ["name"] = "Atal'ai Signet of Serenity", ["text"] = "Binds when picked up\nRequires Level 50\nUse: Permanently adds to a shoulder slot item increased healing done by spells and effects up to 18." }
entries[221324] = { ["name"] = "Brittle Shadowforge Key", ["text"] = "Quest Item\nUnique\nDuration: 15 min\n\"Attaching this crumbling key to your keyring would be impossible.\"" }
entries[221325] = { ["name"] = "EZ-Splode Blasting Charge", ["text"] = "Binds when picked up\nDuration: 15 min\nUse: Blasts open difficult locked doors.\n\"The slow-burning fuse is already lit!\"" }
entries[221326] = { ["name"] = "Sacred Stag Heart", ["text"] = "Binds when picked up\nUse: Present as an offering at the Shrine of the Beast." }
entries[221327] = { ["name"] = "Schematic: Gnomish Shrink Ray", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Shrink Ray\nBinds when equipped\nTrinket\nRequires Engineering (205)\nUse: Shrinks the target reducing their attack power by 250. Thats what it usually does anyway..... (5 Min Cooldown)\nRequires Mithril Tube , Unstable Trigger , Mithril Bar (4), Flask of Mojo (4), Jade (2)" }
entries[221328] = { ["name"] = "Schematic: Gnomish Goggles", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Goggles\nBinds when picked up\nHead Cloth\n45 Armor\n+9 Agility\n+9 Stamina\n+9 Spirit\nDurability 45 / 45\nRequires Engineering (210)\nRequires Fire Goggles , Mithril Tube , Gold Power Core (2), Flask of Mojo (2), Heavy Leather (2)" }
entries[221329] = { ["name"] = "Schematic: Gnomish Net-o-matic Projector", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Net-o-Matic Projector\nBinds when equipped\nTrinket\nRequires Engineering (210)\nUse: Captures the target in a net for 10 sec. The net has a lot of hooks however and sometimes gets caught in the user's clothing when fired...... (10 Min Cooldown)\nRequires Mithril Tube , Shadow Silk (2), Thick Spider's Silk (4), Solid Blasting Powder (2), Mithril Bar (4)" }
entries[221330] = { ["name"] = "Schematic: Gnomish Harm Prevention Belt", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Harm Prevention Belt\nBinds when equipped\nWaist Leather\n66 Armor\n+6 Stamina\nDurability 30 / 30\nRequires Engineering (215)\nUse: A shield of force protects you from the next 500 damage done over the next 10 min. WARNING: Force Field may overload when struck temporarily removing the wearer from this dimension. (Proc chance: 5%) (1 Hour Cooldown)\nRequires Dusky Belt , Mithril Bar (4), Truesilver Bar (2), Unstable Trigger , Aquamarine (2)" }
entries[221331] = { ["name"] = "Schematic: Gnomish Rocket Boots", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Rocket Boots\nBinds when equipped\nFeet Cloth\n41 Armor\nDurability 35 / 35\nRequires Engineering (225)\nUse: These boots significantly increase your run speed for 20 sec. WARNING: Their power supply and gyros do not always function as intended. (30 Min Cooldown)\nRequires Black Mageweave Boots , Mithril Tube (2), Heavy Leather (4), Solid Blasting Powder (8), Gyrochronatom (4)" }
entries[221332] = { ["name"] = "Schematic: Gnomish Battle Chicken", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Battle Chicken\nBinds when picked up\nTrinket\nRequires Engineering (230)\nUse: Creates a Battle Chicken that will fight for you for 1.50 min or until it is destroyed. (30 Min Cooldown)\nRequires Mithril Casing , Truesilver Bar (6), Mithril Bar (6), Inlaid Mithril Cylinder (2), Gold Power Core , Jade (2)" }
entries[221333] = { ["name"] = "Schematic: Gnomish Mind Control Cap", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Mind Control Cap\nBinds when equipped\nHead Cloth\n50 Armor\n+14 Spirit\nDurability 45 / 45\nRequires Engineering (215)\nUse: Engage in mental combat with a humanoid target to try and control their mind. If all works well, you will control the mind of the target for 20 sec ..... (30 Min Cooldown)\nRequires Mithril Bar (10), Truesilver Bar (4), Gold Power Core , Star Ruby (2), Mageweave Cloth (4)" }
entries[221334] = { ["name"] = "Schematic: Gnomish Death Ray", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGnomish Death Ray\nBinds when picked up\nTrinket\nUse: The devices charges over time using your life force and then directs a burst of energy at your opponent. (5 Min Cooldown)\n\"Death or Serious Injury may result from use of this device.\"\nRequires Mithril Tube (2), Unstable Trigger , Essence of Undeath , Ichor of Undeath (4), Inlaid Mithril Cylinder" }
entries[221335] = { ["name"] = "Schematic: Goblin Construction Helmet", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Construction Helmet\nBinds when picked up\nHead Cloth\n44 Armor\n+15 Fire Resistance\nDurability 45 / 45\nRequires Engineering (205)\nUse: Absorbs 300 to 500 Fire damage. Lasts 1 min. (1 Hour Cooldown)\nRequires Mithril Bar (8), Citrine , Elemental Fire (4)" }
entries[221336] = { ["name"] = "Schematic: Goblin Mining Helmet", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Mining Helmet\nBinds when picked up\nHead Mail\n190 Armor\n+15 Stamina\nDurability 60 / 60\nRequires Engineering (205)\nEquip: Mining +5.\nRequires Mithril Bar (8), Citrine , Elemental Earth (4)" }
entries[221337] = { ["name"] = "Schematic: Goblin Mortar", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Mortar\nBinds when equipped\nTrinket\nRequires Engineering (205)\nUse: Inflicts 383 to 517 Fire damage and stuns the targets in a 5 yard radius for 3 sec. (10 Min Cooldown)\n6 Charges\nRequires Mithril Tube (2), Mithril Bar (4), Solid Blasting Powder (5), Gold Power Core , Elemental Fire" }
entries[221338] = { ["name"] = "Schematic: Goblin Sapper Charge", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Sapper Charge\nRequires Engineering (205)\nUse: Explodes when triggered dealing 450 to 750 Fire damage to all enemies nearby and 375 to 625 damage to you. (5 Min Cooldown)\nRequires Mageweave Cloth , Solid Blasting Powder (3), Unstable Trigger" }
entries[221339] = { ["name"] = "Schematic: Goblin Rocket Boots", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Rocket Boots\nBinds when equipped\nFeet Cloth\n41 Armor\nDurability 35 / 35\nUse: These dangerous looking boots significantly increase your run speed for 20 sec. They are prone to explode however, so use with caution. (5 Min Cooldown)\nRequires Black Mageweave Boots , Mithril Tube (2), Heavy Leather (4), Goblin Rocket Fuel (2), Unstable Trigger" }
entries[221340] = { ["name"] = "Schematic: Goblin Bomb Dispenser", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Bomb Dispenser\nBinds when picked up\nTrinket\nRequires Engineering (230)\nUse: Creates a mobile bomb that charges the nearest enemy and explodes for 315 to 385 fire damage. (30 Min Cooldown)\nRequires Mithril Casing (2), Solid Blasting Powder (4), Truesilver Bar (6), Unstable Trigger , Accurate Scope (2)" }
entries[221341] = { ["name"] = "Schematic: The Big One", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nThe Big One\nRequires Engineering (225)\nUse: Inflicts 340 to 460 Fire damage and stuns targets for 5 sec in a 10 yard radius. Any damage will break the effect. (1 Min Cooldown)\nRequires Mithril Casing , Goblin Rocket Fuel , Solid Dynamite (6), Unstable Trigger" }
entries[221342] = { ["name"] = "Schematic: Goblin Dragon Gun", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Dragon Gun\nBinds when picked up\nTrinket\nUse: Deals 61 to 69 fire damage for 10 sec to all targets in a cone in front of the engineer using the weapon. That is unless it explodes..... (5 Min Cooldown)\nRequires Mithril Tube (2), Goblin Rocket Fuel (4), Mithril Bar (6), Truesilver Bar (6), Unstable Trigger" }
entries[221343] = { ["name"] = "Schematic: Goblin Rocket Helmet", ["text"] = "Binds when picked up\nRequires Engineering (205)\nUse:\n\nGoblin Rocket Helmet\nBinds when equipped\nHead Cloth\n50 Armor\n+15 Stamina\nDurability 45 / 45\nRequires Engineering (235)\nUse: Charge an enemy, knocking it silly for 30 seconds. Also knocks you down, stunning you for a short period of time. Any damage caused will revive the target. (20 Min Cooldown)\nRequires Goblin Construction Helmet , Goblin Rocket Fuel (4), Mithril Bar (4), Unstable Trigger" }
entries[221344] = { ["name"] = "Personal Spellbook", ["text"] = "Binds when picked up\nUnique\nHeld In Off-hand\nClasses: Mage\nEquip: Increases damage and healing done by magical spells and effects by up to 21.\nUse: Conjure 5 Comprehension Charms. (4 Hrs Cooldown)" }
entries[221345] = { ["name"] = "Corrupted Blood of Eranikus", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 50" }
entries[221346] = { ["name"] = "Scapula of the Fallen Avatar", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 50\n\"A fine, prestine scapula. It's got a wonderful shape and shows no sign of damage.\"" }
entries[221347] = { ["name"] = "Murky Fire Sapta", ["text"] = "Binds when picked up\nUnique\nUse: Allows the shaman to see elemental spirits." }
