entries[221364] = { ["name"] = "Copper Massacre Coin", ["text"] = "Binds when picked up\nUse: Transmute 100 Copper Massacre Coins into 1 Silver Massacre Coin.\n\"A token of your minor service to the Blood Loa.\"" }
